package org.joda.time;

import java.io.*;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.joda.convert.FromString;
import org.joda.convert.ToString;
import org.joda.time.base.BaseDateTime;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.AbstractReadableInstantFieldProperty;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class MutableDateTime_addYears_TriageGen0Test {

    @Test
    public void testAddYearsPositive() {
        // Test adding a positive number of years
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 0, 0, 0, 0);
        dt.addYears(5);
        assertEquals(2025, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }

    @Test
    public void testAddYearsNegative() {
        // Test adding a negative number of years (subtracting)
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 0, 0, 0, 0);
        dt.addYears(-5);
        assertEquals(2015, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }

    @Test
    public void testAddYearsZero() {
        // Test adding zero years
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 0, 0, 0, 0);
        dt.addYears(0);
        assertEquals(2020, dt.getYear());
    }

    @Test
    public void testAddYearsLeapYearToNonLeapYear() {
        // Test leap year edge case: Feb 29th + 1 year should result in Feb 28th
        MutableDateTime dt = new MutableDateTime(2020, 2, 29, 0, 0, 0, 0);
        dt.addYears(1);
        assertEquals(2021, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(28, dt.getDayOfMonth());
    }

    @Test
    public void testAddYearsNonLeapYearToLeapYear() {
        // Test moving from a non-leap year to a leap year
        MutableDateTime dt = new MutableDateTime(2023, 2, 28, 0, 0, 0, 0);
        dt.addYears(1);
        assertEquals(2024, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(29, dt.getDayOfMonth());
    }

    @Test
    public void testAddYearsLargeValue() {
        // Test adding a very large number of years
        MutableDateTime dt = new MutableDateTime(1000, 1, 1, 0, 0, 0, 0);
        dt.addYears(8000);
        assertEquals(9000, dt.getYear());
    }

    @Test
    public void testAddYearsWithTimePreservation() {
        // Ensure that hours, minutes, seconds, and millis are preserved
        MutableDateTime dt = new MutableDateTime(2020, 5, 15, 12, 30, 45, 500);
        dt.addYears(2);
        assertEquals(2022, dt.getYear());
        assertEquals(5, dt.getMonthOfYear());
        assertEquals(15, dt.getDayOfMonth());
        assertEquals(12, dt.getHourOfDay());
        assertEquals(30, dt.getMinuteOfHour());
        assertEquals(45, dt.getSecondOfMinute());
        assertEquals(500, dt.getMillisOfSecond());
    }
}
